import React, { useContext, useState, useEffect } from 'react';
import { AppContext } from './AppContext';

function SettingsPanel() {
  const { user, setUser, theme, setTheme, language, setLanguage, token } = useContext(AppContext);

  // Initialize form fields with user info
  const [age, setAge] = useState(user?.age || '');
  const [gender, setGender] = useState(user?.gender || '');
  const [name, setName] = useState(user?.name || '');
  const [message, setMessage] = useState(null);

  useEffect(() => {
    // Update form fields if user changes
    setAge(user?.age || '');
    setGender(user?.gender || '');
    setName(user?.name || '');
  }, [user]);

  const toggleTheme = () => {
    setTheme(theme === 'dark' ? 'light' : 'dark');
  };

  const handleLanguageChange = (e) => {
    setLanguage(e.target.value);
  };

  const handleSave = async () => {
    setMessage(null);
    try {
      // API call to update user info
      const res = await fetch('/user/update', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ name, age, gender }),
      });
      if (!res.ok) throw new Error('Update failed');
      
      const updatedUser = await res.json();
      setUser(updatedUser);  // update context with new user data
      setMessage('User info updated successfully!');
    } catch (error) {
      setMessage('Failed to update user info.');
      console.error(error);
    }
  };

  return (
    <div className={`settings-panel ${theme === 'dark' ? 'dark' : ''}`}>
      <h2>Settings</h2>

      <div className="setting-group">
        <label>User ID (readonly)</label>
        <input type="text" value={user?.id || ''} readOnly />
      </div>

      <div className="setting-group">
        <label>Name</label>
        <input
          type="text"
          value={name}
          onChange={(e) => setName(e.target.value)}
          placeholder="Enter your name"
        />
      </div>

      <div className="setting-group">
        <label>Age</label>
        <input
          type="number"
          min="1"
          max="120"
          value={age}
          onChange={(e) => setAge(e.target.value)}
          placeholder="Enter your age"
        />
      </div>

      <div className="setting-group">
        <label>Gender</label>
        <select value={gender} onChange={(e) => setGender(e.target.value)}>
          <option value="">Select gender</option>
          <option value="male">Male</option>
          <option value="female">Female</option>
          <option value="other">Other</option>
        </select>
      </div>

      <div className="setting-group">
        <label>Theme</label>
        <button onClick={toggleTheme}>
          Switch to {theme === 'dark' ? 'Light' : 'Dark'} Mode
        </button>
      </div>

      <div className="setting-group">
        <label>Language</label>
        <select value={language} onChange={handleLanguageChange}>
          <option value="en">English</option>
          <option value="fr">French</option>
          <option value="ar">Arabic</option>
        </select>
      </div>

      <button className="save-btn" onClick={handleSave}>
        Save
      </button>

      {message && <div className="message">{message}</div>}
    </div>
  );
}

export default SettingsPanel;
